with ins as (insert into public.artist_eras (artist_slug,from_year,to_year,sound,tags,source_url,source_name,palette) select x.s,x.f,x.t,x.snd,array(select json_array_elements_text(x.tags)),x.u,x.n,x.p from json_to_recordset('[{"s":"rafiki","f":2017,"t":null,"snd":"House, techno and electro with broken beat influence","tags":["house","techno","electro","breaks","acid"],"u":"https://mixmag.net/feature/the-mix-019-rafiki-dj-interview-mumbai-house-techno-krunk-kulture","n":"Mixmag","p":"ink"}]'::json) as x(s text,f int,t int,snd text,tags json,u text,n text,p text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_eras e where e.artist_slug=x.s and e.from_year=x.f) returning 1) select count(*) from ins;